/* Planet names open source-backed significations; no chart calculation or transit mutation. */
(()=>{'use strict';
const DATA=window.KPPlanetKarkatvaData,LABELS=['Nature','Body','Relationships','Profession','Objects','Life themes'],SYMBOLS={Su:'☉',Mo:'☽',Ma:'♂',Me:'☿',Ju:'♃',Ve:'♀',Sa:'♄',Ra:'☊',Ke:'☋'},COLOURS={Su:'#af6414',Mo:'#376dae',Ma:'#b74e3d',Me:'#22806b',Ju:'#986b14',Ve:'#a44787',Sa:'#53648c',Ra:'#665688',Ke:'#80604b'};
let dialog=null,selected='',returnFocus=null,queued=false;
const language=()=>window.KPPreferences?.get?.().language||'english';
function get(id,lang=language()){const e=DATA.entries[id];if(!e)return null;const mr=lang==='marathi';return {id,language:mr?'marathi':'english',name:mr?e.mrName:e.enName,symbol:SYMBOLS[id],fields:mr?e.mr.map(f=>({...f})):e.en.map((text,i)=>({label:LABELS[i],text})),source:{...DATA.metadata}};}
function node(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
function render(){const lang=language(),mr=lang==='marathi',both=lang==='bilingual',entry=DATA.entries[selected];if(!dialog||!entry)return;dialog.lang=mr?'mr':both?'en-mr':'en';dialog.style.setProperty('--planet-accent',COLOURS[selected]);dialog.querySelector('.kp-planet-symbol').textContent=SYMBOLS[selected];dialog.querySelector('.kp-planet-kicker').textContent=mr?'ग्रह कारकत्व':both?'Planet significations · ग्रह कारकत्व':'Planet significations';dialog.querySelector('h2').textContent=both?entry.enName+' · '+entry.mrName:mr?entry.mrName:entry.enName;const close=dialog.querySelector('button');close.textContent=mr?'बंद करा':both?'Close · बंद करा':'Close';close.setAttribute('aria-label',mr?'ग्रह कारकत्व बंद करा':'Close planet significations');const content=dialog.querySelector('.kp-planet-content');content.replaceChildren();for(const locale of both?['english','marathi']:[mr?'marathi':'english']){const d=get(selected,locale),section=node('section');section.lang=locale==='marathi'?'mr':'en';if(both)section.append(node('h3',locale==='marathi'?'मराठी':'English'));const grid=node('dl');for(const field of d.fields){const group=node('div');group.append(node('dt',field.label),node('dd',field.text));grid.append(group);}section.append(grid);content.append(section);}}
function ensureDialog(){if(dialog)return;dialog=node('dialog');dialog.id='kp-planet-karkatva-dialog';dialog.className='no-print';dialog.setAttribute('data-no-localize','');dialog.setAttribute('aria-labelledby','kp-planet-karkatva-title');const header=node('header'),symbol=node('span');symbol.className='kp-planet-symbol';symbol.setAttribute('aria-hidden','true');const heading=node('div'),kicker=node('span');kicker.className='kp-planet-kicker';const title=node('h2');title.id='kp-planet-karkatva-title';heading.append(kicker,title);const close=node('button');close.type='button';close.onclick=()=>dialog.close();header.append(symbol,heading,close);const content=node('div');content.className='kp-planet-content';dialog.append(header,content);dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();});document.body.append(dialog);}
function open(id,origin){if(!DATA.entries[id])return false;ensureDialog();selected=id;returnFocus=origin||document.activeElement;render();if(!dialog.open)dialog.showModal();dialog.querySelector('button').focus();return true;}
function mark(e,id){if(!e||!DATA.entries[id])return;e.dataset.planetKarkatva=id;e.setAttribute('role','button');e.setAttribute('tabindex','0');e.setAttribute('aria-haspopup','dialog');const d=get(id);e.setAttribute('aria-label',language()==='marathi'?d.name+' · कारकत्व पाहा':d.name+' · View significations');}
function decorate(){queued=false;document.querySelectorAll('#kundali .v38-planet,#home-kundali .v38-planet,#na-native-chart .v38-planet').forEach(e=>mark(e.querySelector('.v38-name'),e.dataset.planet));document.querySelectorAll('#kundali-north svg text[data-planet],#home-kundali svg text[data-planet],#na-native-chart svg text[data-planet],#tc-rashi-chart svg tspan[data-planet],#tc-bhav-chart svg tspan[data-planet]').forEach(e=>mark(e,e.dataset.planet));document.querySelectorAll('#tc-planets tr[data-planet],#tc-planet-nakshatras tr[data-planet]').forEach(e=>mark(e.firstElementChild,e.dataset.planet));document.querySelectorAll('#south9 .kp-planet-label,#home .kp-planet-label,#basic-information .kp-planet-label,#karyesh .kp-planet-label').forEach(e=>{const ref=e.closest('[data-planet-ref]');if(ref)mark(e,ref.dataset.planetRef);});}
function schedule(){if(!queued){queued=true;requestAnimationFrame(decorate);}}
function init(){decorate();const observer=new MutationObserver(schedule);for(const id of ['kundali','kundali-north','home-kundali','na-native-chart','tc-rashi-chart','tc-bhav-chart','tc-planets','tc-planet-nakshatras','south9','home-planets','basic-information','karyesh']){const e=document.getElementById(id);if(e)observer.observe(e,{childList:true,subtree:true});}document.addEventListener('click',event=>{const target=event.target.closest?.('[data-planet-karkatva]');if(target){event.preventDefault();event.stopPropagation();open(target.dataset.planetKarkatva,target);}},true);document.addEventListener('keydown',event=>{if(!['Enter',' '].includes(event.key))return;const target=event.target.closest?.('[data-planet-karkatva]');if(target){event.preventDefault();event.stopPropagation();open(target.dataset.planetKarkatva,target);}},true);window.addEventListener('kp-preferences-changed',()=>{decorate();if(dialog?.open)render();});}
window.KPPlanetKarkatva=Object.freeze({get,open,refresh:decorate});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
